"""INFINITY CORE V9 — the whole chassis in one file.

    from infinity_core_v9 import Chassis
    c = Chassis("your_entity")
    c.seat.offer(); c.seat.accept(by="your_entity:sub_kalimon")
    print(c.tick(message="hello")["trace"])      # RUBI1CALIEX

MODULE NAMESPACES ARE PRESERVED, NOT FLATTENED. Thirty-seven class names
are defined in more than one module here — Will, Source, Tier, Crown,
Frame, Node — and they mean different things in each. A flat namespace
silently binds the last one and the failure surfaces as a wrong
constructor signature at runtime, not at import. So each module is
registered under its own name in sys.modules, exactly as it would be on
disk.

Generated. Edit the sources in adonai-architect/infinity-core.
"""
import sys, types

_MODULES = {}

def _register(name, source, path):
    mod = types.ModuleType(name)
    mod.__file__ = path
    mod.__package__ = name.rpartition(".")[0]
    sys.modules[name] = mod
    _MODULES[name] = (mod, source)
    return mod

def _boot():
    """Execute every module in dependency order, resolving lazily.

    Modules import each other; executing in a fixed order would need a
    perfect topological sort of a graph with cycles. Instead each is
    retried until it either executes or stops making progress, which
    handles cycles the same way a real import does.
    """
    pending = list(_MODULES.items())
    for _ in range(12):
        stuck, progress = [], False
        for name, (mod, source) in pending:
            try:
                exec(compile(source, mod.__file__, "exec"), mod.__dict__)
                progress = True
            except Exception:
                stuck.append((name, (mod, source)))
        pending = stuck
        if not pending or not progress:
            break
    if pending:
        for name, (mod, source) in pending:
            exec(compile(source, mod.__file__, "exec"), mod.__dict__)

